package metrics

// MetricCatalog returns the canonical descriptors for every metric family rendered by Registry.
func MetricCatalog() []MetricDescriptorDTO {
	return []MetricDescriptorDTO{
		{Name: "narumq_audit_events_total", Help: "Management audit events by publication outcome.", Type: MetricTypeCounter, Scope: MetricScopeNode, Aggregation: MetricAggregationIncreaseSum, LabelNames: []string{"outcome"}},
		{Name: "narumq_audit_publisher_ready", Help: "Whether the node-local audit publisher can append events.", Type: MetricTypeGauge, Scope: MetricScopeNode, Aggregation: MetricAggregationPerNode},
		{Name: "narumq_auth_attempts_total", Help: "Total authentication attempts.", Type: MetricTypeCounter, Scope: MetricScopeNode, Aggregation: MetricAggregationIncreaseSum, LabelNames: []string{"method", "reason", "result"}},
		{Name: "narumq_cluster_commit_backlog_oldest_seconds", Help: "Age of the oldest unfinished ingress delivery command.", Type: MetricTypeGauge, Scope: MetricScopeNode, Aggregation: MetricAggregationMax},
		{Name: "narumq_cluster_policy_committed", Help: "Whether a cluster policy is committed locally.", Type: MetricTypeGauge, Scope: MetricScopeReplicated, Aggregation: MetricAggregationPerNode},
		{Name: "narumq_cluster_policy_config_mismatch", Help: "Whether local cluster policy configuration conflicts with the committed policy.", Type: MetricTypeGauge, Scope: MetricScopeNode, Aggregation: MetricAggregationPerNode},
		{Name: "narumq_cluster_policy_version", Help: "Version of the locally applied cluster policy.", Type: MetricTypeGauge, Scope: MetricScopeReplicated, Aggregation: MetricAggregationPerNode},
		{Name: "narumq_connections_active", Help: "Current number of active client connections.", Type: MetricTypeGauge, Scope: MetricScopeNode, Aggregation: MetricAggregationSum},
		{Name: "narumq_connections_total", Help: "Total client connection attempts.", Type: MetricTypeCounter, Scope: MetricScopeNode, Aggregation: MetricAggregationIncreaseSum, LabelNames: []string{"protocol", "result", "transport"}},
		{Name: "narumq_durable_delivery_saturated_targets_total", Help: "Durable delivery targets skipped because committed capacity was saturated.", Type: MetricTypeCounter, Scope: MetricScopeNode, Aggregation: MetricAggregationIncreaseSum},
		{Name: "narumq_messages_dropped_total", Help: "Messages discarded after routing before delivery to one subscriber.", Type: MetricTypeCounter, Scope: MetricScopeNode, Aggregation: MetricAggregationIncreaseSum, LabelNames: []string{"reason"}},
		{Name: "narumq_mqtt_connect_rejected_total", Help: "MQTT CONNECT attempts rejected by protocol and reason.", Type: MetricTypeCounter, Scope: MetricScopeNode, Aggregation: MetricAggregationIncreaseSum, LabelNames: []string{"protocol", "reason"}},
		{Name: "narumq_mqtt_listener_admission_rejected_total", Help: "MQTT listener sockets closed by admission limits before CONNECT.", Type: MetricTypeCounter, Scope: MetricScopeNode, Aggregation: MetricAggregationIncreaseSum, LabelNames: []string{"reason", "transport"}},
		{Name: "narumq_node_drain_active", Help: "Whether the local node has a non-terminal committed drain operation.", Type: MetricTypeGauge, Scope: MetricScopeNode, Aggregation: MetricAggregationPerNode},
		{Name: "narumq_node_drain_progress", Help: "Committed progress of the local node drain operation.", Type: MetricTypeGauge, Scope: MetricScopeNode, Aggregation: MetricAggregationPerNode, LabelNames: []string{"quantity"}},
		{Name: "narumq_node_drain_transitions_total", Help: "Committed node drain phase transitions observed for the local node.", Type: MetricTypeCounter, Scope: MetricScopeNode, Aggregation: MetricAggregationIncreaseSum, LabelNames: []string{"phase"}},
		{Name: "narumq_packets_received_total", Help: "Total MQTT packets received by packet type.", Type: MetricTypeCounter, Scope: MetricScopeNode, Aggregation: MetricAggregationIncreaseSum, LabelNames: []string{"packet_type"}},
		{Name: "narumq_packets_sent_total", Help: "Total MQTT packets sent by packet type.", Type: MetricTypeCounter, Scope: MetricScopeNode, Aggregation: MetricAggregationIncreaseSum, LabelNames: []string{"packet_type"}},
		{Name: "narumq_publish_backpressure_active", Help: "Whether a sampled ingress pressure reason is active.", Type: MetricTypeGauge, Scope: MetricScopeNode, Aggregation: MetricAggregationPerNode, LabelNames: []string{"reason"}},
		{Name: "narumq_publish_backpressure_rejections_total", Help: "New durable publishes rejected by admission reason.", Type: MetricTypeCounter, Scope: MetricScopeNode, Aggregation: MetricAggregationIncreaseSum, LabelNames: []string{"reason"}},
		{Name: "narumq_publish_latency_seconds", Help: "Latency of publish processing in seconds.", Type: MetricTypeHistogram, Scope: MetricScopeNode, Aggregation: MetricAggregationBucketSum},
		{Name: "narumq_raft_peer_replication_lag_entries", Help: "Leader commit entries not yet matched by each peer.", Type: MetricTypeGauge, Scope: MetricScopeLeader, Aggregation: MetricAggregationMax, LabelNames: []string{"peer"}},
		{Name: "narumq_raft_stage_duration_seconds", Help: "Duration of completed Raft driver stages, including failures.", Type: MetricTypeHistogram, Scope: MetricScopeNode, Aggregation: MetricAggregationBucketSum, LabelNames: []string{"stage"}},
		{Name: "narumq_raft_wal_sync_duration_seconds", Help: "Duration of one successful Raft WAL group fsync.", Type: MetricTypeHistogram, Scope: MetricScopeNode, Aggregation: MetricAggregationBucketSum},
		{Name: "narumq_raft_wal_sync_entries", Help: "Raft log entries persisted by one WAL group fsync.", Type: MetricTypeHistogram, Scope: MetricScopeNode, Aggregation: MetricAggregationBucketSum},
		{Name: "narumq_raft_wal_written_bytes_total", Help: "Bytes appended to the Raft WAL including frame headers.", Type: MetricTypeCounter, Scope: MetricScopeNode, Aggregation: MetricAggregationIncreaseSum},
		{Name: "narumq_retained_bytes", Help: "Total bytes stored by retained messages.", Type: MetricTypeGauge, Scope: MetricScopeReplicated, Aggregation: MetricAggregationMax},
		{Name: "narumq_retained_messages", Help: "Current number of retained messages.", Type: MetricTypeGauge, Scope: MetricScopeReplicated, Aggregation: MetricAggregationMax},
		{Name: "narumq_sessions_active", Help: "Current number of active client sessions.", Type: MetricTypeGauge, Scope: MetricScopeNode, Aggregation: MetricAggregationSum, LabelNames: []string{"persistent"}},
		{Name: "narumq_storage_free_bytes", Help: "Filesystem bytes available to the local cluster data directory.", Type: MetricTypeGauge, Scope: MetricScopeNode, Aggregation: MetricAggregationPerNode},
		{Name: "narumq_subscriptions_active", Help: "Current number of active subscriptions.", Type: MetricTypeGauge, Scope: MetricScopeReplicated, Aggregation: MetricAggregationMax},
		{Name: "narumq_tenant_limit_rejections_total", Help: "Requests rejected by tenant connection, session, subscription, payload, or rate limits.", Type: MetricTypeCounter, Scope: MetricScopeNode, Aggregation: MetricAggregationIncreaseSum, LabelNames: []string{"dimension", "tenant"}},
		{Name: "narumq_tenant_quota_config_mismatch", Help: "Whether the local quota configuration conflicts with the committed profile.", Type: MetricTypeGauge, Scope: MetricScopeNode, Aggregation: MetricAggregationPerNode},
		{Name: "narumq_tenant_quota_profile_committed", Help: "Whether a tenant quota profile is committed locally.", Type: MetricTypeGauge, Scope: MetricScopeReplicated, Aggregation: MetricAggregationPerNode},
		{Name: "narumq_tenant_quota_profile_version", Help: "Version of the locally committed tenant quota profile.", Type: MetricTypeGauge, Scope: MetricScopeReplicated, Aggregation: MetricAggregationPerNode},
		{Name: "narumq_tenant_quota_rejections_total", Help: "Committed storage mutations rejected by tenant quota dimension.", Type: MetricTypeCounter, Scope: MetricScopeNode, Aggregation: MetricAggregationIncreaseSum, LabelNames: []string{"dimension", "tenant"}},
		{Name: "narumq_will_outcomes_total", Help: "Final outcomes of registered MQTT Will messages by reason.", Type: MetricTypeCounter, Scope: MetricScopeNode, Aggregation: MetricAggregationIncreaseSum, LabelNames: []string{"reason"}},
	}
}
